BEGIN;

DO $$ 
DECLARE
    v_topic_id UUID;
BEGIN
    -- Fetch the topic ID (using both possible slugs as fallbacks)
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'clinical-reasoning-diagnosis' LIMIT 1;
    IF v_topic_id IS NULL THEN
        SELECT id INTO v_topic_id FROM topics WHERE slug = 'clinical-reasoning-differential' LIMIT 1;
    END IF;

    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic not found for slug clinical-reasoning-diagnosis or clinical-reasoning-differential';
    END IF;

    -- Idempotent Insert for MCQs (Batch 1: 351-450)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation)
    SELECT v_topic_id, t.question, t.options, t.correct_index, t.explanation
    FROM (VALUES
        ('A 65-year-old male with a history of heart failure presents with worsening shortness of breath. Which finding on physical exam has the highest positive likelihood ratio (LR+) for acute heart failure?', '["Bilateral pedal edema", "Jugular venous distention (JVD)", "S3 gallop", "Basilar crackles"]'::jsonb, 2, 'An S3 gallop is highly specific for heart failure in adults, with a very high LR+ (often > 10). While edema and crackles are common, they are less specific.'),
        ('Which cognitive bias is at play when a clinician ignores the high prevalence of a common disease to focus on a rare "zebra" diagnosis because the patient has one unusual symptom?', '["Base-rate neglect", "Anchoring bias", "Framing effect", "Omission bias"]'::jsonb, 0, 'Base-rate neglect involves ignoring the underlying probability (prevalence) of a disease in the population when evaluating a patient.'),
        ('According to the "Big 5" differential for acute shortness of breath, which life-threatening condition must be ruled out in a patient with sudden onset dyspnea and clear breath sounds?', '["Pneumonia", "Pulmonary Embolism", "COPD exacerbation", "Heart Failure"]'::jsonb, 1, 'Pulmonary embolism often presents with sudden dyspnea and a relatively normal lung exam, making it a \"must-not-miss\" in the differential for SOB with clear lungs.'),
        ('A patient presents with acute abdominal pain and "pain out of proportion to exam." This reasoning points most strongly toward:', '["Appendicitis", "Acute Mesenteric Ischemia", "Cholecystitis", "Bowel Obstruction"]'::jsonb, 1, 'Mesenteric ischemia is characterized by severe pain while the physical exam shows a soft, non-tender abdomen early on.'),
        ('In clinical reasoning, "Sutton''s Law" encourages a clinician to:', '["Look for rare diseases", "Go where the money is (perform the test most likely to give the diagnosis)", "Never trust the history", "Always order a CT scan first"]'::jsonb, 1, 'Sutton''s Law suggests focusing on the most likely causes and performing the most high-yield diagnostic steps first.'),
        ('Which physical exam finding is considered a "red flag" for a secondary cause of headache?', '["Photophobia during the headache", "Worsening when lying flat", "Unilateral throbbing pain", "Nausea and vomiting"]'::jsonb, 1, 'Headaches that worsen in the supine position or upon awakening suggest increased intracranial pressure, a major red flag.'),
        ('A 22-year-old female presents with RLQ pain. Which "must-rule-out" diagnosis should be evaluated first in any woman of childbearing age?', '["Appendicitis", "Ectopic Pregnancy", "Ovarian Torsion", "Pelvic Inflammatory Disease"]'::jsonb, 1, 'Ectopic pregnancy is a surgical emergency and must be ruled out with a pregnancy test in any fertile female with abdominal pain.'),
        ('Using Bayesian reasoning, if a test with 90% Sensitivity is negative, it is most useful for ruling out a disease when the pre-test probability is:', '["High", "Low to Moderate", "Very High", "Irrelevant"]'::jsonb, 1, 'A negative test (SnNout) is most powerful when the pre-test probability is not so high that a negative result would still leave a high post-test probability.'),
        ('Which \"On Call\" priority is the most critical when evaluating a patient with a new change in mental status?', '["Ordering a psychiatric consult", "Checking Fingerstick Glucose and Oxygen Saturation", "Ordering a Head CT", "Starting intravenous antibiotics"]'::jsonb, 1, 'Metabolic (Hypoglycemia) and Hypoxic causes are rapidly reversible and must be checked immediately.'),
        ('A patient with jaundice and "clay-colored stools" likely has which type of hyperbilirubinemia?', '["Unconjugated (Pre-hepatic)", "Conjugated (Post-hepatic/Obstructive)", "Mixed", "Hemolytic"]'::jsonb, 1, 'Clay-colored stools (acholic) indicate a lack of bile pigments reaching the gut, characteristic of biliary obstruction.'),
        ('A \"Thunderclap\" headache reaching maximal intensity within 60 seconds is most characteristic of:', '["Migraine", "Subarachnoid Hemorrhage", "Tension headache", "Cluster headache"]'::jsonb, 1, 'Thunderclap onset is a classic \"red flag\" for intracranial hemorrhage.'),
        ('Which finding on a Chest X-ray has the highest specificity for a pneumothorax?', '["Hyperlucency of one lung", "Visualization of a visceral pleural line", "Shift of the trachea", "Flattened diaphragms"]'::jsonb, 1, 'Seeing the pleural line separated from the chest wall is the definitive radiographic sign of a PTX.'),
        ('In a patient with "painless" obstructive jaundice, which malignancy is the most likely culprit in an elderly patient?', '["Hepatocellular carcinoma", "Pancreatic adenocarcinoma (head of pancreas)", "Cholangiocarcinoma", "Lymphoma"]'::jsonb, 1, 'Painless jaundice in the elderly is classically associated with pancreatic head tumors (Courvoisier''s Law).'),
        ('Which cognitive bias involves the tendency to continue a diagnostic or treatment path because significant time and resources have already been invested?', '["Confirmation bias", "Sunk cost fallacy", "Anchoring bias", "Outcome bias"]'::jsonb, 1, 'The sunk cost fallacy can lead to persisting with an incorrect diagnosis or a non-beneficial treatment.'),
        ('A \"Fever of Unknown Origin\" (FUO) requires the fever to have been present for at least how long?', '["1 week", "3 weeks", "1 month", "3 days"]'::jsonb, 1, 'FUO is defined as fever > 38.3°C for at least 3 weeks with no diagnosis after initial investigation.'),
        ('Which physical exam maneuver is used to evaluate for appendicitis by pressing in the LLQ and eliciting pain in the RLQ?', '["McBurney''s sign", "Rovsing''s sign", "Psoas sign", "Murphy''s sign"]'::jsonb, 1, 'Rovsing''s sign indicates referred rebound tenderness due to peritoneal irritation.'),
        ('According to EBM principles, a Likelihood Ratio (LR+) of 10 or greater is considered:', '["Insignificant", "A moderate increase in disease probability", "A large and often conclusive increase in disease probability", "A decrease in disease probability"]'::jsonb, 2, 'An LR+ > 10 significantly \"rules in\" a diagnosis for most clinical scenarios.'),
        ('A patient with "hemoptysis" and "weight loss" who is a heavy smoker should be evaluated first for:', '["Tuberculosis", "Bronchiectasis", "Lung Cancer", "Pulmonary Embolism"]'::jsonb, 2, 'In an elderly smoker, malignancy is the primary reasoning concern for these constitutional and respiratory symptoms.'),
        ('Which type of edema is most characteristic of a systemic problem like Heart Failure or Nephrotic Syndrome?', '["Unilateral pitting edema", "Bilateral pitting edema", "Non-pitting lymphedema", "Local inflammatory edema"]'::jsonb, 1, 'Systemic causes of volume overload or low oncotic pressure typically cause symmetric, bilateral pitting edema.'),
        ('A \"systolic crescendo-decrescendo\" murmur heard best at the right upper sternal border in an elderly patient suggests:', '["Mitral Regurgitation", "Aortic Stenosis", "Tricuspid Regurgitation", "Aortic Regurgitation"]'::jsonb, 1, 'This is the classic presentation of calcific aortic stenosis.'),
        ('Which cognitive heuristic involves judging the probability of a disease based on how "memorable" or "recent" a similar case was?', '["Representativeness", "Availability", "Anchoring", "Framing"]'::jsonb, 1, 'Availability bias leads to over-estimating the frequency of diseases that are currently \"top of mind.\"'),
        ('In a patient with an acute change in mental status, the \"MIST\" mnemonic stands for:', '["Meningitis, Insulin, Stroke, Trauma", "Metabolic, Infectious, Structural, Toxins", "Memory, Intellect, Speech, Thought", "Musculoskeletal, Immune, Skin, Temperature"]'::jsonb, 1, 'MIST is a systematic framework for the differential of delirium.'),
        ('Which lab value is most useful to help rule OUT heart failure as a cause of acute dyspnea in the emergency department?', '["Troponin", "BNP (B-type Natriuretic Peptide)", "D-dimer", "Creatinine"]'::jsonb, 1, 'A BNP < 100 pg/mL has a very high negative predictive value for heart failure.'),
        ('A patient with syncope that occurs during exertion and without any warning (no prodrome) is most concerning for:', '["Vasovagal syncope", "Cardiac syncope (arrhythmia or structural)", "Orthostatic hypotension", "Psychogenic pseudosyncope"]'::jsonb, 1, 'Sudden syncope without a prodrome, especially during exercise, is a \"red flag\" for cardiac etiology.'),
        ('Which physical exam finding has the highest specificity (SpPin) for a Large Pleural Effusion?', '["Dullness to percussion", "Absent breath sounds", "Tracheal deviation", "Egophony above the fluid level"]'::jsonb, 0, 'Dullness to percussion is the most reliable physical sign for detecting pleural fluid.'),
        ('The tendency to stop the diagnostic process once a plausible diagnosis is found is known as:', '["Anchoring", "Premature closure", "Confirmation bias", "Blind spot bias"]'::jsonb, 1, 'Premature closure is the single most common cause of diagnostic error.'),
        ('A \"widened mediastinum\" on a Chest X-ray of a patient with tearing chest pain radiating to the back is classic for:', '["Pulmonary Embolism", "Aortic Dissection", "Myocardial Infarction", "Tension Pneumothorax"]'::jsonb, 1, 'This is a high-yield radiographic sign of a life-threatening aortic emergency.'),
        ('Which reasoning framework categorizes AKI into three buckets based on where the problem occurs relative to the kidney?', '["The Big 5", "Pre-renal, Intrinsic, and Post-renal", "SNOOP", "ABCDE"]'::jsonb, 1, 'This is the standard systematic approach to renal failure.'),
        ('A \"positive\" Murphy''s sign (arrest of inspiration on RUQ palpation) is a reasoning tool for:', '["Appendicitis", "Acute Cholecystitis", "Hepatitis", "Pancreatitis"]'::jsonb, 1, 'It indicates inflammation of the gallbladder reaching the parietal peritoneum.'),
        ('Which cognitive bias describes the tendency to see biases in others but believe you are objective yourself?', '["Framing effect", "Blind spot bias", "Commission bias", "Hindsight bias"]'::jsonb, 1, 'Blind spot bias makes it difficult for clinicians to recognize their own heuristic errors.'),
        ('A patient with acute "pleuritic" chest pain and hemoptysis should be evaluated first for:', '["ACS", "Pulmonary Embolism", "Pneumonia", "Aortic Dissection"]'::jsonb, 1, 'Hemoptysis and pleuritic pain are part of the classic triad for PE (though often absent).'),
        ('According to \"Sutton''s Law,\" if a patient has clear signs of jaundice, you should first check:', '["Brain MRI", "Liver function tests and bilirubin", "CBC", "Thyroid levels"]'::jsonb, 1, 'Go \"where the money is\"—investigate the organ system clearly indicated by the symptoms.'),
        ('A \"sensory level\" (numbness below a certain point on the trunk) localizes a neurological lesion to the:', '["Brain", "Spinal Cord", "Peripheral Nerves", "Nerve Roots"]'::jsonb, 1, 'A dermatomal level is a pathognomonic sign of spinal cord pathology.'),
        ('Which type of vertigo is associated with vertical nystagmus and "red flag" neurological deficits?', '["Peripheral vertigo", "Central vertigo (Brainstem/Cerebellar)", "Benign Paroxysmal Positional Vertigo", "Vestibular neuritis"]'::jsonb, 1, 'Vertical nystagmus is almost always a sign of a central (CNS) problem.'),
        ('A \"narrow pulse pressure\" (e.g., 100/85) in a patient with shortness of breath and high JVP suggests:', '["Aortic Regurgitation", "Cardiac Tamponade or Severe Aortic Stenosis", "Hyperthyroidism", "Anemia"]'::jsonb, 1, 'Low stroke volume leads to a narrowed difference between systolic and diastolic pressures.'),
        ('Which lab test should be ordered for any patient with a suspected "Thunderclap" headache if the initial Head CT is negative?', '["MRI Brain", "Lumbar Puncture", "EEG", "Serum electrolytes"]'::jsonb, 1, 'LP is needed to rule out SAH by checking for RBCs or xantochromia.'),
        ('In clinical reasoning, \"Occam''s Razor\" suggests that:', '["A patient can have many diseases", "The simplest explanation that accounts for all findings is usually correct", "Rare diseases are more common than we think", "Never trust a single test"]'::jsonb, 1, 'This is the principle of parsimony, aiming for a single unifying diagnosis.'),
        ('Which cognitive bias involves judging an outcome as being predictable *after* it has already occurred?', '["Confirmation bias", "Hindsight bias", "Outcome bias", "Anchoring bias"]'::jsonb, 1, 'Hindsight bias makes it difficult to learn from mistakes because the error seems \"obvious\" in reverse.'),
        ('A patient with "ascites" and a Serum-Ascites Albumin Gradient (SAAG) > 1.1 g/dL likely has:', '["Malignancy", "Portal Hypertension (e.g., Cirrhosis)", "Tuberculosis", "Nephrotic syndrome"]'::jsonb, 1, 'A high gradient (>1.1) indicates the fluid is transudative, usually from portal pressure.'),
        ('Which finding on a peripheral smear is a \"must-not-miss\" sign of Microangiopathic Hemolytic Anemia (MAHA) like TTP or DIC?', '["Target cells", "Schistocytes", "Bite cells", "Burr cells"]'::jsonb, 1, 'Schistocytes (fragmented RBCs) are a laboratory emergency indicating active shearing of cells.'),
        ('According to the \"On Call\" protocol, a patient with a \"new\" heart murmur and a fever should be admitted for:', '["Viral illness workup", "Blood cultures and evaluation for endocarditis", "Observation for dehydration", "Routine follow-up"]'::jsonb, 1, 'Endocarditis is a life-threatening \"must-not-miss\" in the fever + new murmur scenario.'),
        ('Which type of dysphagia involves difficulty with BOTH solids and liquids from the onset?', '["Mechanical obstruction (e.g., Cancer)", "Motility disorder (e.g., Achalasia)", "Esophagitis", "GERD"]'::jsonb, 1, 'Mechanical issues usually start with solids; motility issues affect both early on.'),
        ('A \"low\" reticulocyte count in the setting of anemia suggests:', '["Hemolysis", "Acute blood loss", "Inadequate bone marrow production", "Normal response"]'::jsonb, 2, 'The retic count tells you if the \"factory\" is producing enough new cells to compensate for the anemia.'),
        ('Which physical exam sign involves pain in the RUQ when the patient is asked to breathe in while you palpate under the ribs?', '["McBurney''s", "Murphy''s", "Psoas", "Obturator"]'::jsonb, 1, 'Murphy''s sign is the hallmark for acute cholecystitis.'),
        ('In Bayesian reasoning, \"Sensitivity\" (SnNout) is most useful when it is high because a NEGATIVE result:', '["Confirms the disease", "Effectively rules OUT the disease", "Is irrelevant", "Means the test failed"]'::jsonb, 1, 'If a very sensitive test is negative, it is very unlikely the patient has the disease.'),
        ('Which \"red flag\" for back pain suggests a neoplastic or infectious cause?', '["Pain that improves with rest", "Worsening at night or when supine", "Acute onset after lifting", "Unilateral leg pain"]'::jsonb, 1, 'Nocturnal pain that doesn''t resolve with rest is concerning for malignancy or osteomyelitis.'),
        ('A 70-year-old with "sudden, painless loss of vision" in one eye (Amaurosis Fugax) should be evaluated for:', '["Glaucoma", "Carotid artery disease/TIA", "Cataracts", "Migraine"]'::jsonb, 1, 'This is often an embolic event and a warning sign for an impending stroke.'),
        ('Which cognitive bias describes the tendency to follow the lead of other clinicians who have already labeled a patient with a certain diagnosis?', '["Diagnostic momentum", "Availability bias", "Blind spot bias", "Framing effect"]'::jsonb, 0, 'Once a diagnosis like \"delirium\" is written, it gains momentum and is rarely questioned.'),
        ('A patient with "bilateral, symmetric, small-joint" inflammatory arthritis most likely has:', '["Gout", "Rheumatoid Arthritis", "Osteoarthritis", "Septic Arthritis"]'::jsonb, 1, 'Symmetry and small joint involvement are the \"classic\" representativeness for RA.'),
        ('Which \"On Call\" triage priority should be seen first?', '["A patient with a BP of 180/100 and no symptoms", "A patient with a BP of 90/60 and new confusion", "A patient with a sore throat and fever", "A patient requesting a sleeping pill"]'::jsonb, 1, 'Abnormal vitals + End-organ dysfunction (confusion) always take priority.'),
        ('A \"negative\" D-dimer test can safely rule out PE ONLY in patients who have:', '["High pre-test probability", "Low to moderate pre-test probability", "A history of smoking", "A normal CXR"]'::jsonb, 1, 'In high-risk patients, the negative predictive value of D-dimer is not high enough to rule out the disease.'),
        ('Which finding on CXR is most characteristic of \"interstitial\" lung disease (like Pulmonary Edema or Fibrosis)?', '["Lobar consolidation", "Kerley B lines", "Atelectasis", "Hyperinflation"]'::jsonb, 1, 'Kerley B lines are short, horizontal lines at the lung bases indicating fluid/thickening in the septa.'),
        ('In clinical reasoning, \"System 1\" thinking is best described as:', '["Slow and analytical", "Fast, intuitive, and heuristic-based", "Deliberate", "Mathematical"]'::jsonb, 1, 'System 1 is the \"gut feeling\" or pattern recognition mode of thinking.'),
        ('Which physical exam finding characterizes an \"Upper Motor Neuron\" (UMN) lesion?', '["Atrophy and fasciculations", "Spasticity and hyperreflexia", "Hypotonia", "Normal reflexes"]'::jsonb, 1, 'UMN lesions (Brain/Cord) lead to increased tone and \"up-going\" Babinski.'),
        ('A patient with "polyuria" and "hypernatremia" whose urine remains dilute after desmopressin has:', '["Central Diabetes Insipidus", "Nephrogenic Diabetes Insipidus", "SIADH", "Primary Polydipsia"]'::jsonb, 1, 'Failure to concentrate urine after ADH (desmopressin) proves the kidneys are resistant.'),
        ('Which cognitive bias involves the presentation of information (e.g., 90% survival vs 10% mortality) influencing a decision?', '["Framing effect", "Anchoring bias", "Availability bias", "Sunk cost fallacy"]'::jsonb, 0, 'People often make different choices based on whether the \"frame\" is a gain or a loss.'),
        ('A \"positive\" psoas sign (pain on hip extension) is used to evaluate for:', '["Cholecystitis", "Appendicitis (especially retrocecal)", "Hepatitis", "Renal stones"]'::jsonb, 1, 'It indicates irritation of the psoas muscle, usually by an inflamed appendix.'),
        ('Which \"must-not-miss\" diagnosis should be considered in an elderly patient with \"new-onset anemia and weight loss\"?', '["Iron deficiency from diet", "Colon Cancer", "Hemorrhoids", "Peptic ulcer"]'::jsonb, 1, 'Iron deficiency in an older adult is GI malignancy until proven otherwise.'),
        ('In clinical reasoning, \"System 2\" thinking is used when:', '["The case is routine and familiar", "The case is complex, unfamiliar, or \"System 1\" fails", "The doctor is in a hurry", "Pattern recognition is easy"]'::jsonb, 1, 'System 2 is the slow, deliberate, and logical checking mode.'),
        ('Which electrolyte abnormality is most likely to cause \"refractory\" hypokalemia that does not respond to replacement?', '["Hyponatremia", "Hypomagnesemia", "Hypercalcemia", "Hyperphosphatemia"]'::jsonb, 1, 'Low magnesium leads to excessive potassium secretion in the kidney; you must fix the Mg first.'),
        ('A patient with "hematochezia" (bright red blood per rectum) and hemodynamic instability (low BP) likely has:', '["Hemorrhoids", "A brisk Upper GI bleed", "Slow colon cancer", "IBD flare"]'::jsonb, 1, 'If the patient is unstable with red blood per rectum, it often means the blood is moving too fast for digestion (brisk UGI bleed).'),
        ('Which \"On Call\" finding is most concerning in a patient with a \"Sore Throat\"?', '["Fever of 101F", "Drooling and inability to swallow secretions", "Tender cervical nodes", "Red tonsils"]'::jsonb, 1, 'Drooling suggests airway obstruction (e.g., Epiglottitis or Peritonsillar abscess), a medical emergency.'),
        ('According to Learning Radiology, a \"silhouette sign\" on CXR helps to:', '["Identify a tumor", "Localize an opacity by its loss of a normal border", "Determine heart size", "Measure lung volume"]'::jsonb, 1, 'If the heart border is lost, the opacity is in the anterior lung (e.g., RML or Lingula).'),
        ('A patient with "syncope" followed by a "post-ictal" period of confusion for 20 minutes likely had a:', '["Vasovagal episode", "Seizure", "Cardiac arrhythmia", "TIA"]'::jsonb, 1, 'Syncope usually has immediate recovery; seizures involve a period of re-orientation.'),
        ('Which cognitive bias involves the tendency to see patterns or significance in random data?', '["Confirmation bias", "Illusory correlation", "Anchoring", "Sunk cost"]'::jsonb, 1, 'Clinicians may \"see\" a relationship between a treatment and a result that isn''t truly there.'),
        ('A patient with "pleuritic" chest pain that is relieved by "sitting forward" most likely has:', '["Myocardial Infarction", "Pericarditis", "Pulmonary Embolism", "Pneumothorax"]'::jsonb, 1, 'Positional relief is a hallmark of pericardial inflammation.'),
        ('Which lab test is the \"Gold Standard\" for diagnosing a Pulmonary Embolism in a stable patient?', '["D-dimer", "CT Pulmonary Angiogram (CTPA)", "CXR", "ABG"]'::jsonb, 1, 'CTPA is the definitive imaging modality for PE in the modern ER.'),
        ('A \"positive\" Rovsing''s sign in the LLQ causing pain in the RLQ is an example of:', '["Visceral pain", "Referred rebound tenderness", "Somatic pain", "Psychogenic pain"]'::jsonb, 1, 'It indicates parietal peritoneal irritation in the RLQ.'),
        ('Which type of bias occurs when a clinician only looks for symptoms that confirm their initial hunch?', '["Confirmation bias", "Search satisficing", "Availability bias", "Base-rate neglect"]'::jsonb, 0, 'This is a key driver of diagnostic error.'),
        ('In a patient with "altered mental status," what is the most important \"plumbing\" check (Post-renal)?', '["Ordering a Head CT", "Bladder scan or checking for a blocked Foley catheter", "Checking the liver enzymes", "Looking for pneumonia"]'::jsonb, 1, 'Urinary retention is a very common and easily fixed cause of delirium in the elderly.'),
        ('A patient with "unilateral" leg swelling and a history of recent surgery has a Wells Score of 3 (High). What is the next best step?', '["Order a D-dimer", "Order a Venous Duplex Ultrasound", "Discharge with NSAIDs", "Wait for 24 hours"]'::jsonb, 1, 'In high-risk patients, skip the D-dimer and go straight to imaging.'),
        ('Which \"must-not-miss\" condition presents with \"sudden, tearing chest pain radiating to the back\"?', '["Myocardial Infarction", "Aortic Dissection", "Tension Pneumothorax", "Esophageal Rupture"]'::jsonb, 1, 'Dissection must be considered in anyone with \"tearing\" or \"ripping\" pain.'),
        ('In clinical reasoning, \"Premature Closure\" often happens because we fail to:', '["Order enough tests", "Generate an adequate differential diagnosis and seek evidence for alternatives", "Memorize enough diseases", "Ask the patient enough questions"]'::jsonb, 1, 'Stopping the search for \"the answer\" too early is a major cognitive trap.'),
        ('Which finding on physical exam is most specific for a \"Tension\" Pneumothorax (as opposed to a simple one)?', '["Absent breath sounds", "Tracheal deviation away from the affected side", "Hyperresonance", "Tachypnea"]'::jsonb, 1, 'Tracheal deviation and hemodynamic instability (hypotension) indicate \"tension.\"'),
        ('According to Bates, which maneuver is most useful to identify a "hidden" inguinal hernia?', '["Palpating the scrotum during a cough (invagination method)", "Visual inspection only", "Auscultation", "Percussion"]'::jsonb, 0, 'The invagination of the scrotal skin allows the finger to reach the inguinal canal.'),
        ('A patient with "hypotension" and "bradycardia" after a spinal injury likely has:', '["Septic shock", "Neurogenic shock", "Hypovolemic shock", "Cardiogenic shock"]'::jsonb, 1, 'Loss of sympathetic tone leads to both low pressure and a failure to reflexively increase the heart rate.'),
        ('Which \"heuristic\" is the most likely cause of a doctor missing a diagnosis during an epidemic?', '["Representativeness", "Availability", "Anchoring", "Sunk cost"]'::jsonb, 1, 'The \"availability\" of recent similar cases (the epidemic) biases the doctor toward that one diagnosis.'),
        ('A patient with "diarrhea" and "hypokalemia" will typically have what urine potassium level?', '["High (> 20 mEq/L)", "Low (< 15-20 mEq/L)", "Normal", "Undetectable"]'::jsonb, 1, 'If the loss is from the gut (GI loss), the healthy kidney should conserve potassium, leading to a low urine K.'),
        ('In a patient with "acute abdominal pain," which finding on exam is the most specific for \"Peritonitis\"?', '["Tenderness to deep palpation", "Involuntary guarding and rigidity", "Soft abdomen", "Bowel sounds"]'::jsonb, 1, 'Rigidity and \"rebound\" tenderness are the hallmarks of peritoneal inflammation.'),
        ('Which cognitive bias involves the clinician being influenced by the "outcome" of a previous similar decision?', '["Confirmation bias", "Outcome bias", "Hindsight bias", "Anchoring"]'::jsonb, 1, 'Judging a decision as good or bad based on the result, rather than the logic at the time.'),
        ('A patient with "sudden, unilateral weakness" that resolves completely within 1 hour has had a:', '["Stroke", "TIA (Transient Ischemic Attack)", "Migraine", "Seizure"]'::jsonb, 1, 'TIA is a \"warning\" event with no permanent tissue damage on imaging.'),
        ('According to the \"ABCDE\" approach to the \"Sick Patient,\" what does the \"D\" stand for?', '["Diagnosis", "Disability (Neurological status)", "Dehydration", "Discharge"]'::jsonb, 1, 'Disability includes GCS score, pupils, and basic focal deficits.'),
        ('Which finding on CXR is most concerning for \"perforated viscus\" (e.g., burst stomach ulcer)?', '["Consolidation", "Free air under the diaphragm", "Pleural effusion", "Atelectasis"]'::jsonb, 1, 'Pneumoperitoneum (free air) is a surgical emergency.'),
        ('A patient with "weight loss," "night sweats," and "hemoptysis" has what reasoning \"triad\"?', '["Cancer", "Tuberculosis", "Heart failure", "Asthma"]'::jsonb, 1, 'Constitutional symptoms + hemoptysis = TB (especially in endemic areas) or Malignancy.'),
        ('Which cognitive bias involves the clinician \"ignoring\" a patient''s symptom because it doesn''t fit the diagnosis they have already chosen?', '["Confirmation bias", "Blind spot bias", "Availability bias", "Base-rate neglect"]'::jsonb, 0, 'This is the active \"filtering\" of information to match a hunch.'),
        ('A \"positive\" psoas sign in a patient with abdominal pain suggests the appendix is in what position?', '["Anterior", "Retrocecal", "Pelvic", "Pre-ileal"]'::jsonb, 1, 'A retrocecal appendix irritates the psoas muscle, causing pain on hip extension.'),
        ('Which lab finding is most specific for \"prerenal\" azotemia as the cause of AKI?', '["FeNa > 2%", "FeNa < 1%", "Urine Na > 40", "Muddy brown casts"]'::jsonb, 1, 'Low fractional excretion of sodium shows the kidney is still working to conserve salt/volume.'),
        ('In clinical reasoning, \"Search Satisficing\" is when the clinician:', '["Orders all the tests", "Stops looking for more abnormalities after finding one (e.g., seeing one fracture and missing the second)", "Finds the right diagnosis", "Discharges the patient"]'::jsonb, 1, 'It is a common trap in radiology and trauma.'),
        ('A patient with "syncope" that occurs while shaving or wearing a tight collar likely has:', '["Vasovagal syncope", "Carotid sinus hypersensitivity", "Cardiac syncope", "Orthostatic hypotension"]'::jsonb, 1, 'Mechanical stimulation of the carotid sinus triggers a reflexive drop in HR/BP.'),
        ('Which cognitive bias involves the clinician being overly confident in their initial \"System 1\" intuition?', '["Overconfidence bias", "Anchoring bias", "Framing effect", "Sunk cost fallacy"]'::jsonb, 0, 'This prevents the clinician from engaging \"System 2\" to check their work.'),
        ('A patient with "bilateral" leg swelling and "low albumin" likely has:', '["Heart Failure", "Nephrotic Syndrome or Liver Failure", "DVT", "Lymphedema"]'::jsonb, 1, 'Low oncotic pressure leads to systemic \"leakage\" into the tissues.'),
        ('According to Bates, a \"widened\" area of cardiac dullness on percussion suggests:', '["Pneumothorax", "Pericardial effusion or severe Cardiomegaly", "Normal variant", "COPD"]'::jsonb, 1, 'Though less common now than ultrasound, percussion can still detect a large \"water-bottle\" heart.'),
        ('Which finding on a fundoscopic exam is a \"red flag\" for chronic hypertension?', '["Cotton wool spots", "AV nicking and silver wiring", "Papilledema", "Normal disc"]'::jsonb, 1, 'Arteriovenous (AV) nicking is a sign of long-standing vascular damage.'),
        ('A \"positive\" Murphy''s sign has what characteristic in its predictive value?', '["High Sensitivity", "High Specificity for cholecystitis", "Low Accuracy", "High NPV"]'::jsonb, 1, 'It is highly specific when positive, helping \"rule in\" the diagnosis.'),
        ('Which cognitive bias is the most likely reason for \"triage cueing\" (e.g., assuming a known alcoholic is just drunk when they actually have a subdural hematoma)?', '["Availability", "Anchoring (to the triage label)", "Framing", "Sunk cost"]'::jsonb, 1, 'Anchoring to the initial label prevents fresh reasoning.'),
        ('In a patient with "altered mental status," which metabolic abnormality is a common and easily fixed cause?', '["Hypernatremia", "Hypoglycemia", "Hypercalcemia", "Hyperkalemia"]'::jsonb, 1, 'Always check a \"fingerstick\" glucose in AMS.'),
        ('Which physical exam finding is the most reliable for \"ruling out\" a large pleural effusion?', '["Resonance to percussion", "Absent breath sounds", "Normal vocal fremitus", "Tracheal position"]'::jsonb, 0, 'If you hear resonance (normal) instead of dullness, a large effusion is very unlikely (SnNout).'),
        ('A patient with "chest pain" and "ST-segment elevation" in leads II, III, and aVF is having an MI in which location?', '["Anterior", "Inferior", "Lateral", "Septal"]'::jsonb, 1, 'These leads view the bottom (inferior) surface of the heart, usually supplied by the RCA.'),
        ('In clinical reasoning, \"Metacognition\" is the process of:', '["Learning more facts", "Thinking about how you think (reflecting on your own cognitive processes to catch biases)", "Memorizing guidelines", "Following orders"]'::jsonb, 1, 'Metacognition is the primary tool for \"de-biasing\" your diagnostic process.')
    ) AS t(question, options, correct_index, explanation)
    WHERE NOT EXISTS (
        SELECT 1 FROM mcqs m 
        WHERE m.topic_id = v_topic_id 
        AND m.question = t.question
    );

    RAISE NOTICE 'SUCCESS: Batch 1 (MCQs 351-450) processed idempotently with fixed JSON syntax.';
END $$;

COMMIT;
